    """
    if not numbers:
        return []
    if len(numbers) < 2:
        # If there's only one element, it becomes both min and max,
        # so it should be rescaled to 0.
        return [0.0] * len(numbers)

    min_val = min(numbers)
    max_val = max(numbers)

    if max_val == min_val:
        # If all numbers are the same, they should all become 0.
        return [0.0] * len(numbers)
    else:
