    30 = 2 * 3 * 5
    """

    if a < 2:
        return False

    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    prime_factors = []
    temp_a = a
    for i in range(2, a + 1):
        if is_prime(i):
            while temp_a % i == 0:
                prime_factors.append(i)
                temp_a //= i
        if temp_a == 1:
            break

    return len(prime_factors) == 3 and temp_a == 1

def any_int(x, y, z):
    if not all(isinstance(arg, int) for arg in [x, y, z]):
        return False

    return (x == y + z) or (y == x + z) or (z == x + y)

def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    encoded_message = []
    vowels = 'aeiouAEIOU'

    for char in message:
        if char.isalpha():
            # Swap case
            swapped_char = char.swapcase()

            # Replace vowels
            if swapped_char in vowels:
                # Determine original case of the vowel
                is_upper = swapped_char.isupper()

                # Get the ASCII value, add 2, and convert back to char
                # Handle wrapping around 'z' or 'Z'
                if is_upper:
                    if swapped_char == 'Y':
                        new_char = 'A'
                    elif swapped_char == 'Z':
                        new_char = 'B'
                    else:
                        new_char = chr(ord(swapped_char) + 2)
                else: # lowercase
                    if swapped_char == 'y':
                        new_char = 'a'
                    elif swapped_char == 'z':
                        new_char = 'b'
                    else:
                        new_char = chr(ord(swapped_char) + 2)

                encoded_message.append(new_char)
            else:
                encoded_message.append(swapped_char)
        else:
            encoded_message.append(char)

    return "".join(encoded_message)

