    counts = {}
    for x in lst:
        counts[x] = counts.get(x, 0) + 1
        if counts[x] > 2:  # Changed from > 1 to > 2 based on examples
            return False

    # Check for ascending order
    for i in range(len(lst) - 1):
        if lst[i] > lst[i+1]:
